import {FHS_PLAQUETTE_REFERENCE} from './fhs-plaquette-reference.js?v=20261117-phonopy1';

export const FHS_PLAQUETTE_BRIDGE_HOOKS=Object.freeze({'geometry-topology':Object.freeze(['oriented-plaquette'])});
const owners=new WeakMap(),clone=value=>JSON.parse(JSON.stringify(value));let svgSerial=0;
const esc=value=>String(value??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const fmt=value=>value===null||value===undefined?'—':Math.abs(value)<5e-14?'0':Number(value.toPrecision(7)).toString();
const parametersText=result=>'QWZ · m='+fmt(result.parameters.mass)+' · N='+fmt(result.parameters.mesh)+' · s='+fmt(result.parameters.gaugeStrength);
const mul=(a,b)=>[a[0]*b[0]-a[1]*b[1],a[0]*b[1]+a[1]*b[0]],conj=z=>[z[0],-z[1]],abs=z=>Math.hypot(z[0],z[1]),distance=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]);
const zfmt=z=>z===null?'—':Math.abs(z[1])<5e-14?fmt(z[0]):Math.abs(z[0])<5e-14?fmt(z[1])+'i':fmt(z[0])+(z[1]<0?' − ':' + ')+fmt(Math.abs(z[1]))+'i';
