const select=(id,label,rows,value)=>`<label for="${id}">${esc(label)}<select id="${id}">${rows.map(([v,text])=>`<option value="${esc(v)}"${String(v)===String(value)?' selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
