/** Inspect four production overlaps only; no Hamiltonian/eigenvector solver. */
export function fhsPlaquetteLedger(result,{cellId='interior',frame='before'}={}){
 const replay=result?.fhsReplay;
 if(result?.model!=='qwz'||!replay)return null;
 if(replay.schemaVersion!==1||replay.convergenceIndex!==0||!Number.isInteger(replay.mesh)||replay.mesh<9||replay.mesh!==result.parameters?.mesh||replay.sewing!=='identity'||replay.orientation!=='kx then ky'||replay.complexEncoding!=='[real,imag]'||replay.linkThreshold!==1e-10||typeof replay.bandIsolated!=='boolean'||typeof replay.beforeLinksValid!=='boolean'||typeof replay.afterLinksValid!=='boolean'||!['before','after'].includes(frame))throw Error('Invalid FHS replay metadata.');
 const cell=replay.cells?.find(row=>row.id===cellId);
 if(!cell||!Array.isArray(cell.anchor)||cell.anchor.length!==2||!cell.anchor.every(x=>Number.isInteger(x)&&x>=0&&x<replay.mesh)||cell.corners?.length!==4||cell.gaugePhases?.length!==4||!cell.gaugePhases.every(finite))throw Error('Invalid FHS replay cell.');
 for(const corner of cell.corners)if(!Array.isArray(corner.index)||corner.index.length!==2||!corner.index.every(x=>Number.isInteger(x)&&x>=0&&x<replay.mesh)||!pair(corner.k)||!pair(corner.unwrappedK))throw Error('Invalid FHS replay corner.');
 const stages={};
 for(const name of ['before','after']){
  const raw=cell[name]?.rawForwardOverlaps;if(!Array.isArray(raw)||raw.length!==4||!raw.every(pair))throw Error('Invalid FHS replay overlaps.');
  const magnitudes=raw.map(abs),valid=replay.bandIsolated&&replay[name+'LinksValid']&&magnitudes.every(value=>value>replay.linkThreshold);
  const units=raw.map((value,i)=>magnitudes[i]>replay.linkThreshold?value.map(x=>x/magnitudes[i]):null),factors=units.map((value,i)=>value===null?null:i<2?value:conj(value));
  const products=[];let product=[1,0];if(valid)for(const value of factors){product=mul(product,value);products.push(product);}
  const loop=valid?product:null,flux=valid?-Math.atan2(loop[1],loop[0]):null,issuedLoop=cell[name].loop,issuedFlux=cell[name].fluxRad;
  if(valid){if(!pair(issuedLoop)||!finite(issuedFlux)||distance(loop,issuedLoop)>2e-14||Math.abs(flux-issuedFlux)>2e-14)throw Error('FHS replay product differs from production.');}
  else if(issuedLoop!==null||issuedFlux!==null)throw Error('Invalid FHS replay must retain null loop and flux.');
  stages[name]={raw:clone(raw),magnitudes,units,factors,products,loop,flux,valid,edgePhases:valid?factors.map(z=>Math.atan2(z[1],z[0])):null};
 }
 const endpoints=[[0,1],[1,2],[2,3],[3,0]],phaseDifferences=endpoints.map(([a,b])=>cell.gaugePhases[b]-cell.gaugePhases[a]);
 const covariance=stages.before.factors.map((value,i)=>value&&stages.after.factors[i]?distance(mul(value,[Math.cos(phaseDifferences[i]),Math.sin(phaseDifferences[i])]),stages.after.factors[i]):null);
 const valid=stages.before.valid&&stages.after.valid;
 if(valid&&covariance.some(value=>value===null||value>2e-13))throw Error('FHS replay endpoint phases differ from production.');
 return{mesh:replay.mesh,convergenceIndex:0,cell:clone(cell),frame,stages,current:stages[frame],phaseDifferences,covariance,
  endpointPhaseSum:phaseDifferences.reduce((a,b)=>a+b,0),loopDifference:valid?distance(stages.before.loop,stages.after.loop):null,
  principalEdgePhaseSum:stages[frame].edgePhases?.reduce((a,b)=>a+b,0)??null,
  branchInteger:valid?Math.round((stages[frame].edgePhases.reduce((a,b)=>a+b,0)+stages[frame].flux)/(2*Math.PI)):null};
}

/** Complete, supported input from a real reference or this result's parameters. */
export function fhsPlaquetteLabRequest(values={}){
 const input=values.result?.parameters||reference(values.caseId).input,keys=['model','mass','energyScale','t1','t2','mesh','pathSamples','gaugeStrength','kx','ky'];
 if(input?.model!=='qwz'||keys.some(key=>!Object.hasOwn(input,key)))throw Error('A complete QWZ input is required.');
 return{action:'quantum_geometry_lab',module:'geometry',input:Object.fromEntries(keys.map(key=>[key,clone(input[key])]))};
}
const questions=[
 {prompt:'从 C 沿 −x 走到 D，应使用哪个因子？',answer:'conjugate',options:[['conjugate','Ux(D) 的复共轭'],['forward','直接使用 Ux(D)'],['start','使用 Ux(C)']],feedback:{conjugate:'正确。原数组保存 D→C 的正向链；反走 C→D 必须取复共轭。',forward:'Ux(D) 是 D→C。反走时相位应变号，因此要复共轭。',start:'Ux(C) 指向 C 右侧的另一个格点，不是这条回路的 C→D。'}},
 {prompt:'四条主值边相位相加可能多出 2π。怎样求本格通量？',answer:'product',options:[['product','先乘四个复数因子，再取 −Arg'],['sum','直接取四个显示相位之和的负值'],['plus','直接取环路乘积的 +Arg']],feedback:{product:'正确。主值边相位可能跨分支，先相乘才能统一取主值；本站再取负号。',sum:'每一条显示相位各自取过主值；它们的和可相差整倍 2π，必须回到复数乘积。',plus:'本站使用 A=i⟨u|∂u⟩ 与 kx→ky 定向，生产实现取 −Arg。'}},
 {prompt:'一个单元的通量非零，能否据此给整个能带判定 Chern 数？',answer:'whole',options:[['whole','不能，还要完整 BZ 求和并检查能隙与网格'],['cell','能，这个通量就是 Chern 数'],['two','把保存的两个单元相加就足够']],feedback:{whole:'正确。这里仅保存两个单元供回放；完整基网格总和来自 convergence[0]，主结果还要通过细网格与全局能隙检查。',cell:'单格通量的单位是 rad；Chern 数来自完整 BZ 的通量总和除以 2π。',two:'两个示例不能代替 N² 个单元。m=3 还展示了局部非零而总和为零的情况。'}},
 {prompt:'越过 +π 边界连接到保存的 −π 顶点时，本模型使用什么 sewing？',answer:'identity',options:[['identity','固定周期轨道基底中的单位矩阵'],['minus','额外乘一个自旋的负号'],['omit','跳过这条边界链']],feedback:{identity:'正确。这里的两个分量是固定轨道基底，周期边界使用 identity sewing；本征矢任意相位仍由闭环消掉。',minus:'本模型没有加入自旋的 2π 旋转或额外负号。轨道 sewing 已明确为单位矩阵。',omit:'漏掉边界链会把 Brillouin 环面切开，不能得到本站的完整 FHS 求和。'}}
];
const initial=()=>({open:false,proofOpen:false,caseId:reference().id,cellId:'interior',frame:'before',step:0,choices:['','','',''],checked:[false,false,false,false],note:'',copyOutcome:''});
function restore(saved){const state=initial();if(!saved||typeof saved!=='object')return state;for(const field of ['open','proofOpen'])state[field]=saved[field]===true;if(references().some(row=>row.id===saved.caseId))state.caseId=saved.caseId;if(['interior','boundary-xy'].includes(saved.cellId))state.cellId=saved.cellId;if(['before','after'].includes(saved.frame))state.frame=saved.frame;if(Number.isInteger(saved.step))state.step=Math.max(0,Math.min(8,saved.step));if(typeof saved.note==='string')state.note=saved.note.slice(0,2000);for(let i=0;i<4;i++)if(questions[i].options.some(([id])=>id===saved.choices?.[i])){state.choices[i]=saved.choices[i];state.checked[i]=saved.checked?.[i]===true;}return state;}
const getResult=(state,result)=>result||reference(state.caseId).result;
function loopSVG(step){const active=Math.max(0,Math.min(4,step-2)),arrow='fpb-arrow-'+(++svgSerial);return `<svg class="fpb-loop" viewBox="0 0 300 220" role="img" aria-label="A到B到C到D的定向单元"><defs><marker id="${arrow}" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="currentColor"></path></marker></defs>${['M70 170 L230 170','M250 150 L250 70','M230 50 L70 50','M50 70 L50 150'].map((d,i)=>`<path d="${d}"${i<active?' class="fpb-active"':''} marker-end="url(#${arrow})"></path>`).join('')}${[[50,170,'A'],[250,170,'B'],[250,50,'C'],[50,50,'D']].map(([x,y,t])=>`<circle cx="${x}" cy="${y}" r="17"></circle><text class="fpb-label" x="${x}" y="${y+6}" text-anchor="middle">${t}</text>`).join('')}<text x="143" y="204">+x</text><text x="264" y="116">+y</text><text x="139" y="27">−x</text><text x="12" y="116">−y</text></svg>`;}
function coordinatesHTML(ledger){const c=ledger.cell;return loopSVG(0)+table('四个实际顶点：数组索引按 [ky,kx]，动量按 (kx,ky)',['顶点','索引','保存的 k','沿回路的 unwrapped k','α / rad'],c.corners.map((v,i)=>[['A','B','C','D'][i],v.index.join(', '),v.k.map(fmt).join(', '),v.unwrappedK.map(fmt).join(', '),fmt(c.gaugePhases[i])]))+'<p>边界单元把保存的 −π 视作沿正方向到达的 +π；这是环面上的相邻点。本站固定周期轨道基底使用 identity sewing，不额外添加负号。</p>';}
function ledgerHTML(state,result){
 const r=fhsPlaquetteLedger(result,state),s=r.current,steps=Math.max(0,Math.min(4,state.step-2));
 let html=loopSVG(state.step)+table('先保存正向重叠，再归一化；最后两条沿回路反走',['正向数组项','原始复数重叠','模','单位链','回路因子','定向边主值相位 / rad'],['rx(A)：A→B','ry(B)：B→C','rx(D)：D→C','ry(A)：A→D'].map((label,i)=>[label,zfmt(s.raw[i]),fmt(s.magnitudes[i]),state.step>=1?zfmt(s.units[i]):'—',state.step>=2?zfmt(s.factors[i]):'—',state.step>=2?fmt(s.edgePhases?.[i]):'—']));
 if(!s.valid)return html+'<p class="fpb-warning">本次能带闭隙或链重叠无效。原始重叠仅作有限网格诊断；生产 loop 与 flux 为未定义，不把这些数值补成 Chern 结果。</p>';
 if(state.step>=1)html+=formula('U_\\mu=\\frac{r_\\mu}{|r_\\mu|}');
 if(state.step>=2)html+=formula('L=U_x(A)U_y(B)U_x(D)^*U_y(A)^*')+'<p>第三、四项取复共轭，分别把 D→C 和 A→D 反向为 C→D 和 D→A。</p>';
 if(steps)html+=table('按 A→B→C→D→A 顺序逐项相乘',['已乘边数','累计复数乘积'],s.products.slice(0,steps).map((value,i)=>[i+1,zfmt(value)]));
 if(state.step>=7)html+=table('四条定向边的主值相位',['路径','相位 / rad'],['A→B','B→C','C→D','D→A'].map((path,i)=>[path,fmt(s.edgePhases[i])]))+formula('\\phi=-\\operatorname{Arg}(L)')+table('主值分支：先乘复数，再取一次 Arg',['比较量','值','单位'],[['四个显示边相位的直接和',fmt(r.principalEdgePhaseSum),'rad'],['Arg(L)',fmt(-s.flux),'rad'],['本站单元通量 −Arg(L)',fmt(s.flux),'rad'],['相位和与 Arg(L) 相差的 2π 倍数',r.branchInteger,'1']])+'<p>整数倍 2π 来自各边相位各自的主值分支；不能把显示相位的直接和当作最终单元通量。</p>';
 return html;
}
function gaugeHTML(state,result){const r=fhsPlaquetteLedger(result,state);if(state.step<8)return '<p>完成四条边和负 Arg 的回放后，再展开最后一步，核对同一次计算中的规范端点抵消。</p>';return table('同一次计算的规范前后：每一条定向边比较端点相位',['路径','α终−α始','原因子','变相位因子','端点变换残差'],['A→B','B→C','C→D','D→A'].map((name,i)=>[name,fmt(r.phaseDifferences[i]),zfmt(r.stages.before.factors[i]),zfmt(r.stages.after.factors[i]),fmt(r.covariance[i])]))+formula('(\\alpha_B-\\alpha_A)+(\\alpha_C-\\alpha_B)+(\\alpha_D-\\alpha_C)+(\\alpha_A-\\alpha_D)=0')+table('闭环保持不变；单边显示相位可跨越主值分支',['量','值'],[['四个端点差之和',fmt(r.endpointPhaseSum)],['规范前 loop',zfmt(r.stages.before.loop)],['规范后 loop',zfmt(r.stages.after.loop)],['两个 loop 的复数距离',fmt(r.loopDifference)]])+'<p>这是实际保存的 before/after 数据。改的是同一带本征矢的 U(1) 相位，轨道基底与 sewing 保持不变。</p>';}
function totalHTML(result,ledger){const rows=result.convergence||[];return table('本格、基网格与主结果分别记账',['对象','数值','范围'],[['本格通量 φ / rad',fmt(ledger.current.flux),'一个单元'],['基网格 FHS 总和 C_N',fmt(rows[0]?.value),'N='+ledger.mesh+'，convergence[0]'],['细网格 FHS 总和',fmt(rows[1]?.value),'N='+String(rows[1]?.mesh??'—')+'，convergence[1]'],['当前主 Chern 结果',fmt(result.topology?.value),'通过解析能隙与两层网格检查后报告']])+formula('C_N=\\frac{1}{2\\pi}\\sum_{j,i}\\phi_{ji}')+'<p data-math-ignore>本卡只回放两个真实单元，不用它们估算 N² 个单元的总和。完整基网格值来自原有 convergence[0]；主结果使用细网格，不能把本卡的 N 网格单元冒充细网格贡献。m=3 可以有非零局部通量而总 Chern 为零。</p>';}
function questionHTML(prefix,state,i){return `<section class="fpb-question"><h4>${questions[i].prompt}</h4>${select(prefix+'-q'+i,'先记录预测',[['','请选择'],...questions[i].options],state.choices[i])}${button(prefix+'-check'+i,'核对并解释',!state.choices[i])}<p id="${prefix}-feedback${i}" class="fpb-feedback" role="status"></p></section>`;}
function bodyHTML(prefix,state,result,mode,canCopy){const actual=getResult(state,result),ledger=fhsPlaquetteLedger(actual,state);return '<p class="fpb-scope">下带、kx→ky 定向、固定周期轨道基底。本卡读取真实 FHS 四边重叠；有限复数运算用于展开已计算的数据，不重新求解 Hamiltonian。</p>'+'<p id="'+prefix+'-parameters" data-math-ignore>'+esc(parametersText(actual))+'</p>'+`<div class="fpb-controls">${mode==='lesson'?select(prefix+'-case','真实 Python 参考',references().map(row=>[row.id,'QWZ · m='+row.input.mass+', N='+row.input.mesh+', s='+row.input.gaugeStrength]),state.caseId):''}${select(prefix+'-cell','选择本次保存的单元',[['interior','内部单元'],['boundary-xy','越过 x、y 周期边界']],state.cellId)}${select(prefix+'-frame','显示哪一组实际链',[['before','原本征矢'],['after','k 依赖规范变相位后']],state.frame)}</div>`+`<section class="fpb-stage"><h3>1 · 顶点、定向与周期边界</h3><div id="${prefix}-coordinates">${coordinatesHTML(ledger)}</div></section><section class="fpb-stage"><h3>2 · 四条边逐项构造闭环</h3>${button(prefix+'-step','下一步',!ledger.current.valid)}<output id="${prefix}-step-number">${state.step}/8</output><div id="${prefix}-ledger">${ledgerHTML(state,actual)}</div></section><section class="fpb-stage"><h3>3 · 规范端点逐个抵消</h3><div id="${prefix}-gauge">${gaugeHTML(state,actual)}</div></section><section class="fpb-stage"><h3>4 · 一格通量与完整 BZ 求和</h3><div id="${prefix}-total">${totalHTML(actual,ledger)}</div></section><section class="fpb-stage"><h3>预测检查</h3>${questions.map((_q,i)=>questionHTML(prefix,state,i)).join('')}</section>`+`<details class="fpb-reference" data-fpb-native="proof"${state.proofOpen?' open':''}><summary>数据来源、适用范围与复现</summary><p>学习页的四个有限参考由真实 quantum_geometry_lab 生成；结果页只使用本次 result.fhsReplay，不替换为参考案例。原始链顺序为 rx(A)、ry(B)、rx(D)、ry(A)，最后两项在回路中复共轭。来源 hash 使用 UTF-8 与 LF 规范化。</p><p data-math-ignore>scripts/check-fhs-plaquette-reference.py --check</p><p>SSH 是一维 Zak 链，没有二维 FHS 单元。旧记录若未保存 fhsReplay，需要重新运行以取得本次四边数据。</p></details>`+(mode==='lesson'&&canCopy?button(prefix+'-copy','把这个完整参考输入复制到原实验')+'<p>复制只填写完整受支持 QWZ 输入，并清除旧表单草稿；仍须手动运行。单元索引、规范边相位、预测与笔记不作为核心输入。</p>':'<p>本卡不自动计算，也不写入完成记录。请在原实验中手动运行以更新结果。</p>')+`<p id="${prefix}-copy-status" class="fpb-feedback" role="status"></p><label class="fpb-note" for="${prefix}-note">${'写一句自己的解释（仅保存在当前页面内存）'}<textarea id="${prefix}-note" rows="3" maxlength="2000">${esc(state.note)}</textarea></label>${button(prefix+'-reset','重置这张回放卡')}`;}

